#!/bin/zsh
# run.sh: main (de016f69 build) listed runs on the five corpora; main + 490 listed and 490 expanded on repo fixtures/.
# 490 listed/expanded corpus runs are reused from list-main-props/runs (same binary d884334e, same flags).
MAIN=/Users/gabe/Projects/caliper-fixtures/oracle-run/target/release/caliper-docgen
PR=/Users/gabe/Projects/caliper-fixtures/shrink/list-main-props/target/release/caliper-docgen
C=/Users/gabe/Projects/caliper-fixtures/corpora
OUT=/Users/gabe/Projects/caliper-fixtures/oracle-run/pattern-eval/runs
FX=/Users/gabe/Projects/caliper/.claude/worktrees/agent-a664ef066cde44793/fixtures
mkdir -p $OUT
typeset -A SRC
SRC=(chakra $C/chakra-ui/packages/react/src mantine $C/mantine/packages/@mantine/core/src antd $C/ant-design/components
     shadcn $C/shadcn-ui/apps/v4 spectrum $C/react-spectrum/packages)
x() { $1 extract --src $2 --json --quiet --no-cache --load-dependencies --collapse-inherited-props $3 > $4 2> $4.err; echo "$4 exit=$?"; }
x $MAIN $FX dependencies $OUT/fixtures.main.json
x $PR $FX dependencies $OUT/fixtures.pr.json
x $PR $FX none $OUT/fixtures.expanded.json
for c in shadcn antd mantine spectrum chakra; do x $MAIN $SRC[$c] dependencies $OUT/$c.main.json; done
echo done
"""Pattern evaluation of PR 490's listing rule: main listed vs 490 listed, 490 expanded for declaring sources.

eval.py <lib> <main.json> <pr.json> <expanded.json> [--fixtures]   (--fixtures splits by fixtures/<lib>/)
Prints per-library row stats, hidden-member classes, top hidden names, pattern buckets. Scratch, not repo code.
"""
import collections
import json
import re
import statistics
import sys

AMBIENT_RE = re.compile(r'/@types/react/|/node_modules/react/|/typescript/lib/lib\.dom|/@react-types/shared/src/dom\.d\.')


def load(p):
    return json.load(open(p))


def rows(d, c):
    out = {}
    for s in c.get('props') or []:
        for n, pid in d['propSets'][s].items():
            out[n] = d['props'][pid]
    for n, pid in (c.get('notableInherited') or {}).items():
        out[n] = d['props'][pid]
    return out


def layer_members(d, c):
    out = {}
    for l in c.get('inheritance') or []:
        m = l.get('members')
        for n in (d['nameLists'][m] if m else []):
            out[n] = l
    return out


def ambient(f):
    return bool(f and AMBIENT_RE.search(f))


def short(f):
    if not f:
        return '(own)'
    f = f.split('node_modules/')[-1]
    return '/'.join(f.split('/')[-3:])


def classify(name, src, size, own_file):
    """src = (typeName, fileName) or None."""
    if src is None:
        return 'c'
    tn, fn = src
    if ambient(fn):
        return 'a'
    if 'csstype' in (fn or '') or name.startswith('_') or size > 200 or re.search(r'System|Condition|StyleProps|CSSProp', tn or ''):
        return 'b'
    if size <= 200:
        return 'c'
    return 'd'


src_cache = {}


def text(path):
    if path not in src_cache:
        try:
            src_cache[path] = open(path).read()
        except OSError:
            src_cache[path] = ''
    return src_cache[path]


def pattern(c, exp_rows, name):
    t = text(c['filePath'])
    det = c.get('detectedBy') or ''
    if '/node_modules/' in c['filePath'] or re.search(r'export\s*\{[^}]*\}\s*from\s*["\'](?!\.)', t) and not re.search(
            r'(function|const)\s+' + re.escape(name.split('.')[-1]) + r'\b', t):
        return 'reexport-dependency'
    if 'actory' in det or re.search(r'\b(chakra|styled|createLeaf|factory|polymorphicFactory|createComponent|withContext|withProvider)\(', t) and re.search(
            r'(const|let)\s+' + re.escape(name.split('.')[-1]) + r'\s*=\s*(chakra|styled|createLeaf|factory|polymorphicFactory|createComponent|withContext|withProvider)', t):
        return 'factory-built'
    if '.' in name or any(e.get('members') for e in c.get('exports') or []) or re.search(
            re.escape(name) + r'\.[A-Z]\w*\s*=', t):
        return 'compound-namespace'
    if re.search(r'\buse[A-Z]\w*\(\s*(props|\{\s*\.\.\.props)', t):
        return 'hook-driven'
    if 'as' in exp_rows and ('asChild' in exp_rows or re.search(r'\bas\??\s*:', t) or 'polymorphic' in t.lower()):
        return 'polymorphic-as'
    if c.get('discriminantProp') or re.search(r'Props\s*<\s*\w+\s+extends', t) or re.search(r'extends\s+[^?{;]+\?[^:;]+:', t):
        return 'generic-conditional'
    if re.search(r'<[a-z][\w.-]*\b[^>]*\{\s*\.\.\.\s*\w+\s*\}', t):
        return 'dom-spread-wrapper'
    if det in ('forwardRef', 'memo') or re.search(r'\b(forwardRef|memo)\(', t):
        return 'forwardRef-memo'
    if not c.get('inheritance') and all(p.get('parent') is None or not ambient(p['parent'].get('fileName')) for p in exp_rows.values()):
        return 'own-props-only'
    return 'other'


def pct(xs, q):
    if not xs:
        return 0
    xs = sorted(xs)
    return xs[min(len(xs) - 1, int(round(q * (len(xs) - 1))))]


def lib_of(c, lib, fixtures):
    if not fixtures:
        return lib
    m = re.search(r'/fixtures/([^/]+)/', c['filePath'])
    return m.group(1) if m else 'fixtures-other'


def main():
    lib, mp, pp, ep = sys.argv[1:5]
    fixtures = '--fixtures' in sys.argv
    M, P, E = load(mp), load(pp), load(ep)
    per = collections.defaultdict(lambda: {'m': [], 'p': [], 'grew': 0, 'fell': 0, 'cls': collections.Counter(),
                                           'top': collections.Counter(), 'topsrc': {}, 'pat': collections.defaultdict(list),
                                           'cands': []})
    for key, pc in P['components'].items():
        mc, ec = M['components'].get(key), E['components'].get(key)
        if mc is None:
            continue
        L = per[lib_of(pc, lib, fixtures)]
        mr, pr = rows(M, mc), rows(P, pc)
        er = rows(E, ec) if ec else dict(mr)
        L['m'].append(len(mr))
        L['p'].append(len(pr))
        if len(pr) - len(mr) > 30:
            L['grew'] += 1
        if len(mr) and len(pr) < 0.1 * len(mr):
            L['fell'] += 1
        size = collections.Counter((p['parent']['name'], p['parent']['fileName']) for p in er.values() if p.get('parent'))
        layers = layer_members(P, pc)
        hidden = {}
        for n in set(mr) - set(pr):
            hidden[n] = 'main-row'
        for n in set(layers) - set(pr):
            p = er.get(n)
            src = (p['parent']['name'], p['parent']['fileName']) if p and p.get('parent') else None
            lay = layers[n]
            if src is None:
                src = (lay.get('typeName'), lay.get('fileName'))
            if not ambient(src[1]) and size.get(src, lay.get('totalProps') or 0) <= 200:
                hidden.setdefault(n, 'api-sized-layer')
        for n, why in hidden.items():
            p = er.get(n) or mr.get(n)
            src = (p['parent']['name'], p['parent']['fileName']) if p and p.get('parent') else None
            if src is None and n in layers:
                src = (layers[n].get('typeName'), layers[n].get('fileName'))
            sz = size.get(src, (layers[n].get('totalProps') if n in layers else 0) or 0) if src else 0
            k = classify(n, src, sz, pc['filePath'])
            L['cls'][k] += 1
            L['top'][n] += 1
            L['topsrc'].setdefault(n, collections.Counter())[(src[0] if src else '(own)') + ' @ ' + short(src[1] if src else None) + f' [{sz}]'] += 1
            if k == 'c':
                L['cands'].append((key, n, src[0] if src else '(own)', short(src[1] if src else None), sz, why))
        pat = pattern(pc, er, pc.get('displayName') or key)
        L['pat'][pat].append((key, len(mr), len(pr), sorted(pr)[:8], sorted(hidden)[:8], len(hidden)))
    out = {}
    for name, L in sorted(per.items()):
        print(f"## {name}: components {len(L['m'])}; median main {statistics.median(L['m']) if L['m'] else 0} -> 490 "
              f"{statistics.median(L['p']) if L['p'] else 0}; p95 {pct(L['m'], .95)} -> {pct(L['p'], .95)}; "
              f"total {sum(L['m'])} -> {sum(L['p'])}; grew>30 {L['grew']}; fell>90% {L['fell']}")
        print(f"   hidden classes: a={L['cls']['a']} b={L['cls']['b']} c={L['cls']['c']} d={L['cls']['d']}")
        print('   top hidden: ' + '; '.join(f"{n} x{k} ({L['topsrc'][n].most_common(1)[0][0]})" for n, k in L['top'].most_common(15)))
        cs = collections.Counter((c[1], c[2], c[3], c[4], c[5]) for c in L['cands'])
        print('   (c) candidates top: ' + '; '.join(f"{n} [{s} @ {f} size {sz}, {w}] x{k}" for (n, s, f, sz, w), k in cs.most_common(15)))
        for pat, items in sorted(L['pat'].items()):
            print(f"   pattern {pat}: {len(items)}; median {statistics.median([i[1] for i in items])} -> {statistics.median([i[2] for i in items])}")
        out[name] = {'pat': {k: v for k, v in L['pat'].items()}, 'cands': L['cands']}
    json.dump(out, open(f'/Users/gabe/Projects/caliper-fixtures/oracle-run/pattern-eval/{lib}.patterns.json', 'w'))


main()

